input.new_string:
    larch_err 'Usage: design-postplan-emit.sh --design-tmpdir PATH [--snapshot-original] [--force-validate] [--repo OWNER/REPO]'
}

validate_repo() {
    local value="$1"
    case "$value" in
        '' | *$'\n'* | *$'\r'* | /* | *../*) fail 'invalid --repo' ;;
    esac
    [[ "$value" =~ ^[A-Za-z0-9._-]+/[A-Za-z0-9._-]+$ ]] || fail 'invalid --repo'
}
